            if ((((long) NmLayerGet(ws, k, 0)) * 10000) < (nonpaper * ((long) minper))) {
                NmLset(ws, k, 0, 0);
            }
            k += 1;
        }
        NmReassignDead(ws, nseeds, merge, pl, pa, pb);
        NmRestat(ws, nseeds);
        // merge centroids within `merge`, the smaller into the larger, until none is
        i = 1;
        while (i == 1) {
            i = 0;
            j = 0;
            k = 0;
            while (k < nseeds) {
                id = k + 1;
                c = 0;
                while (c < k) {
                    if (NmLayerGet(ws, c, 0) > 0) {
                        if (NmLayerGet(ws, k, 0) > 0) {
                            if (NmDist(NmLayerGet(ws, c, 1), NmLayerGet(ws, c, 2), NmLayerGet(ws, c, 3), NmLayerGet(ws, k, 1), NmLayerGet(ws, k, 2), NmLayerGet(ws, k, 3)) <= merge) {
                                if (i == 0) {
                                    i = 1;
                                    j = c;
                                    d = k;
                                }
                            }
                        }
                    }
                    c += 1;
                }
                k += 1;
            }
            if (i == 1) {
                // layer rows j and d (j < d) merge: the larger absorbs the smaller
                if (NmLayerGet(ws, j, 0) < NmLayerGet(ws, d, 0)) {
                    c = j;
                    j = d;
                    d = c;
                }
                // j keeps, d dies
                bin = 0;
                while (bin < 4096) {
                    if (emon.Port.CellsAt(ws, NmWsAssign() + bin) == (d + 1)) {
                        emon.Port.CellsSet(ws, NmWsAssign() + bin, j + 1);
