                            bigger += 1;
                        }
                    }
                    c += 1;
                }
                emon.Port.CellsSet(ws, NmWsLut() + k, bigger + 1);
            }
            k += 1;
        }
        bin = 0;
        while (bin < 4096) {
            id = emon.Port.CellsAt(ws, NmWsAssign() + bin);
            if (id > 0) {
                emon.Port.CellsSet(ws, NmWsAssign() + bin, emon.Port.CellsAt(ws, NmWsLut() + (id - 1)));
            }
            bin += 1;
        }
        // clear the old rows, then restat the new ones
        k = 0;
        while (k < NmMaxLayers()) {
            c = 0;
            while (c < NmLstride()) {
                NmLset(ws, k, c, 0);
                c += 1;
            }
            k += 1;
        }
        bin = 0;
        while (bin < 4096) {
            emon.Port.CellsSet(ws, NmWsLut() + bin, 0);
            bin += 1;
        }
        NmRestat(ws, live);
        emon.Port.CellsSet(ws, NmWsMisc(), live);
