    internal static int NmShareGe(int n, long npix, int bgper) {
        // 1 when `n` pixels are at least `bgper` per mille of `npix`.
        if ((((long) n) * 1000) >= (npix * ((long) bgper))) {
            return 1;
        }
        return 0;
    }
    public static int NmRoles(emon.Port.Cells ws, int light, int chroma, int bgper) {
        // Guess each layer's role (`ir`, SPEC 8.2). A layer covering `bgper` per mille of the page is `background` when it is
        // light or coloured and `unknown` when it is dark and neutral (a mass, not text); otherwise chroma over `chroma` is
        // `colour`, a neutral layer of lightness `light` or more is `light`, and a neutral dark one is `body`: EVERY such layer,
        // since black headings and dark-grey text on one page are two clusters and one kind of ink. Answers the largest body
        // layer's row, or -1.
        int nl = NmLayerCount(ws);
        long npix = (long) NmPixels(ws);
        int k = 0;
        int ch = 0;
        int l = 0;
        int big = 0;
        int body = -1;
        int role = 0;
        while (k < nl) {
            ch = NmAbs(NmLayerGet(ws, k, 2)) + NmAbs(NmLayerGet(ws, k, 3));
            l = NmLayerGet(ws, k, 1);
            big = NmShareGe(NmLayerGet(ws, k, 0), npix, bgper);
            if (ch >= chroma) {
                role = Evidence.IrColor();
            } else if (l >= light) {
                role = Evidence.IrLight();
            } else {
                role = Evidence.IrBody();
            }
            if (big == 1) {
                if (role == Evidence.IrBody()) {
                    role = Evidence.IrUnknown();
                } else {
                    role = Evidence.IrBackground();
                }
            }
            NmLset(ws, k, 8, role);
            if (role == Evidence.IrBody()) {
                if (body < 0) {
                    body = k;
                } else if (NmLayerGet(ws, k, 0) > NmLayerGet(ws, body, 0)) {
                    body = k;
                }
            }
            k += 1;
        }
        return body;
    }
    public static int NmRoleMaskInto(emon.Port.Bitmap src, emon.Port.Cells ws, int role, emon.Port.Bitmap mask) {
        // The mask of every layer whose role is `role`, as one LUT pass: the body mask is the union of the body layers.
        int bin = 0;
        int id = 0;
        while (bin < 4096) {
            id = emon.Port.CellsAt(ws, NmWsAssign() + bin);
            if (id > 0) {
                if (NmLayerGet(ws, id - 1, 8) == role) {
                    emon.Port.CellsSet(ws, NmWsLut() + bin, 255);
                } else {
                    emon.Port.CellsSet(ws, NmWsLut() + bin, 0);
                }
            } else {
                emon.Port.CellsSet(ws, NmWsLut() + bin, 0);
            }
            bin += 1;
        }
        emon.Port.BitmapLutInto(src, ws, NmWsLut(), mask);
        return 0;
    }
    public static int NmMaskInto(emon.Port.Bitmap src, emon.Port.Cells ws, int layer, emon.Port.Bitmap mask) {
        // The ink-mask of layer `layer` (1-based): 255 where the pixel's colour bin belongs to it, else 0. One LUT pass.
        int bin = 0;
        while (bin < 4096) {
            if (emon.Port.CellsAt(ws, NmWsAssign() + bin) == layer) {
                emon.Port.CellsSet(ws, NmWsLut() + bin, 255);
            } else {
                emon.Port.CellsSet(ws, NmWsLut() + bin, 0);
            }
            bin += 1;
        }
        emon.Port.BitmapLutInto(src, ws, NmWsLut(), mask);
        return 0;
    }
    public static int NmLabelInto(emon.Port.Bitmap src, emon.Port.Cells ws, emon.Port.Bitmap labels) {
        // Every pixel's layer id (0 paper, 1..K) in one LUT pass.
        emon.Port.BitmapLutInto(src, ws, NmWsAssign(), labels);
        return 0;
    }
    public static int NmInkRows(emon.Port.Cells inks, emon.Port.Cells ws, int page, int view) {
        // Append one `inks` row per layer (SPEC 8.4.4): the centroid colour packed 0xRRGGBB, lightness 0..1000, chroma
        // (|a| + |b|), pixel count, role, the mask view (-1 here), spread. Answers the first row's index (or the count).
        int nl = NmLayerCount(ws);
