        int r = 0;
        int first = -1;
        while (k < nl) {
            r = Evidence.IkNew(inks, page, view);
            if (first < 0) {
                first = r;
            }
            Evidence.IkSet(inks, r, Evidence.IkfColor(), (((NmLayerGet(ws, k, 4)) << (16)) + ((NmLayerGet(ws, k, 5)) << (8))) + NmLayerGet(ws, k, 6));
            Evidence.IkSet(inks, r, Evidence.IkfLight(), ((NmLayerGet(ws, k, 1) * 1000) + 127) / 255);
            Evidence.IkSet(inks, r, Evidence.IkfChroma(), NmAbs(NmLayerGet(ws, k, 2)) + NmAbs(NmLayerGet(ws, k, 3)));
            Evidence.IkSet(inks, r, Evidence.IkfCount(), NmLayerGet(ws, k, 0));
            Evidence.IkSet(inks, r, Evidence.IkfRole(), NmLayerGet(ws, k, 8));
            Evidence.IkSet(inks, r, Evidence.IkfSpread(), NmLayerGet(ws, k, 7));
            k += 1;
        }
        return first;
    }
    public static int NmSvSize(int w, int r) {
        // Cells `nm-sauvola` uses: a 65536-entry square-root table, then two rings of 2r + 2 integral rows of w + 1.
        return 65536 + ((2 * (((2 * r) + 2) * (w + 1))) * 1);
    }
    public static int NmSqrtTable(emon.Port.Cells t) {
        int i = 0;
        int k = 0;
        while (i < 65536) {
            while (((k + 1) * (k + 1)) <= i) {
                k += 1;
            }
            emon.Port.CellsSet(t, i, k);
            i += 1;
        }
        return 0;
    }
    internal static int NmSvRow(emon.Port.Cells sv, emon.Port.Bitmap g, int k, int rr, int w1, int sqoff) {
        // Integral row k (1..h) from row k - 1 and the pixel row k - 1; rows live in slot k mod rr of each ring.
        int w = w1 - 1;
        int cur = 65536 + ((k % rr) * w1);
        int prev = 65536 + (((k - 1) % rr) * w1);
        int x = 0;
        int v = 0;
        int rs = 0;
        int rq = 0;
        int a = 0;
        int b = 0;
        emon.Port.CellsSet(sv, cur, 0);
        emon.Port.CellsSet(sv, cur + sqoff, 0);
        while (x < w) {
            v = emon.Port.BitmapU8(g, x, k - 1, 0);
            rs += v;
            rq += v * v;
            a = emon.Port.CellsAt(sv, (prev + x) + 1);
            b = emon.Port.CellsAt(sv, ((prev + sqoff) + x) + 1);
            emon.Port.CellsSet(sv, (cur + x) + 1, (int) (((long) a) + ((long) rs)));
            emon.Port.CellsSet(sv, ((cur + sqoff) + x) + 1, (int) (((long) b) + ((long) rq)));
            x += 1;
        }
        return 0;
    }
    internal static int NmWin(emon.Port.Cells sv, int top, int bot, int x0, int x1) {
        // The window sum of one ring: four reads of its two live integral rows `top` and `bot` (offsets), as `ras-win`.
        long s = 0;
        s = (long) emon.Port.CellsAt(sv, bot + x1);
        s -= (long) emon.Port.CellsAt(sv, top + x1);
        s -= (long) emon.Port.CellsAt(sv, bot + x0);
        s += (long) emon.Port.CellsAt(sv, top + x0);
        return (int) s;
    }
    public static int NmSauvola(emon.Port.Bitmap g, emon.Port.Bitmap m, int r, int k, emon.Port.Cells sv) {
        // mask := 255 where the pixel is under the Sauvola threshold of its (2r + 1)-square window (clipped at the edges),
        // else 0; answers the ink count. The same arithmetic as `ras-sauvola`, but over rings of 2r + 2 integral rows, so
        // memory is O(w r). `sv` is a scratch `Cells` (`nm-sv-size` cells are made).
        int w = emon.Port.BitmapW(g);
        int h = emon.Port.BitmapH(g);
        int w1 = emon.Port.BitmapW(g) + 1;
        int rr = (2 * r) + 2;
        int sqoff = rr * w1;
        int y = 0;
        int x = 0;
        int nxt = 1;
        int y0 = 0;
        int y1 = 0;
        int x0 = 0;
        int x1 = 0;
        int n = 0;
        int s = 0;
        int q = 0;
        int mean = 0;
        int vr = 0;
        int sd = 0;
        int thr = 0;
        int top = 0;
        int bot = 0;
        int ink = 0;
        if (emon.Port.CellsLen(sv) < NmSvSize(w, r)) {
            emon.Port.CellsDrop(sv, 0);
            emon.Port.CellsGrow(sv, NmSvSize(w, r), 0);
            NmSqrtTable(sv);
        }
        // slot 0 of both rings is the zero row
        x = 0;
        while (x < w1) {
            emon.Port.CellsSet(sv, 65536 + x, 0);
            emon.Port.CellsSet(sv, (65536 + sqoff) + x, 0);
            x += 1;
        }
        while (y < h) {
            y0 = y - r;
            if (y0 < 0) {
                y0 = 0;
            }
            y1 = (y + r) + 1;
            if (y1 > h) {
                y1 = h;
            }
            while (nxt <= y1) {
                NmSvRow(sv, g, nxt, rr, w1, sqoff);
                nxt += 1;
            }
            top = 65536 + ((y0 % rr) * w1);
            bot = 65536 + ((y1 % rr) * w1);
            x = 0;
            while (x < w) {
                x0 = x - r;
                if (x0 < 0) {
                    x0 = 0;
                }
                x1 = (x + r) + 1;
                if (x1 > w) {
                    x1 = w;
                }
