                    ink += 1;
                } else {
                    emon.Port.BitmapSetU8(m, x, y, 0, 0);
                }
                x += 1;
            }
            y += 1;
        }
        return ink;
    }
    public static int NmSkewPoints(emon.Port.Bitmap m, emon.Port.Cells pts, int ystep, int limit) {
        // The ink RUNS of a binary view into `pts` as (x, y, weight) triples: on every `ystep`-th row, each run of ink by its
        // midpoint x with its length as the weight (a run's pixels all project within a pixel of its midpoint at the angles
        // tried, so this is the row projection of the ink without visiting a pixel twice). At most `limit` runs. Answers how many.
        int w = emon.Port.BitmapW(m);
        int h = emon.Port.BitmapH(m);
        int y = ystep / 2;
        int x = 0;
        int ce = 0;
        int np = 0;
        emon.Port.CellsDrop(pts, 0);
        while ((y < h) && (np < limit)) {
            x = emon.Port.BitmapNextNonzero(m, 0, y);
            while ((x < w) && (np < limit)) {
                ce = x;
                while ((ce < w) && (emon.Port.BitmapU8(m, ce, y, 0) != 0)) {
                    ce += 1;
                }
                emon.Port.CellsPush(pts, (x + ce) / 2);
                emon.Port.CellsPush(pts, y);
                emon.Port.CellsPush(pts, ce - x);
                np += 1;
                x = emon.Port.BitmapNextNonzero(m, ce, y);
            }
            y += ystep;
        }
        return np;
    }
    internal static long NmSkewScore(emon.Port.Cells pts, int np, emon.Port.Cells prof, int cdeg, int off, int nb) {
        // The projection profile's sharpness at one angle: with the text lines at `cdeg` (they RISE to the right by it,
        // centi-degrees counter-clockwise), y*cos + x*sin is the same along a line; the score is the sum of squared
        // counts of ink per two-pixel row, differenced: the sum of squared steps between neighbouring rows, which is largest
        // when the lines' edges fall into few rows (a rotation made by integer shears leaves one-pixel stairs, which two-pixel
        // rows do not see). `prof` has `nb` + 1 cells and is left zero.
        int co = Evidence.EvCos(cdeg);
        int si = Evidence.EvSin(cdeg);
        int i = 0;
        int b = 0;
        int c = 0;
        int pc = 0;
        long sc = 0;
        while (i < np) {
            b = (((emon.Port.CellsAt(pts, (3 * i) + 1) * co) + (emon.Port.CellsAt(pts, 3 * i) * si)) + off) >> (17);
            c = emon.Port.CellsAt(prof, b);
            emon.Port.CellsSet(prof, b, c + emon.Port.CellsAt(pts, (3 * i) + 2));
            i += 1;
        }
        b = 0;
        while (b <= nb) {
            c = emon.Port.CellsAt(prof, b);
            sc += ((long) (c - pc)) * ((long) (c - pc));
            pc = c;
            emon.Port.CellsSet(prof, b, 0);
            b += 1;
        }
        return sc;
    }
    public static int NmDeskew(emon.Port.Bitmap m, emon.Port.Cells pts, emon.Port.Cells prof) {
        // The skew of a binary view in centi-degrees (positive: the text lines rise to the right, counter-clockwise, the
        // sign of `vwf-deskew`): projection profiles of the ink runs over -5..5 degrees at 0.1, then 0.01 around the best;
        // 0 when the best is not clearly better than 0 (over 1/64) or there are under 50 runs. `pts` and `prof` are scratch.
        int w = emon.Port.BitmapW(m);
        int h = emon.Port.BitmapH(m);
        int off = w * 6000;
        int nb = (((((h - 1) * 65536) + ((w - 1) * 6000)) + off) >> (17)) + 2;
        int ystep = (h / 800) + 1;
        int np = 0;
        int a = 0;
        int best = 0;
        long bs = 0;
        long s = 0;
        long s0 = 0;
        if (h > 16000) {
            return 0;
        }
        np = NmSkewPoints(m, pts, ystep, 120000);
        if (np < 50) {
            return 0;
        }
        emon.Port.CellsDrop(prof, 0);
        emon.Port.CellsGrow(prof, nb + 1, 0);
        s0 = NmSkewScore(pts, np, prof, 0, off, nb);
        bs = s0;
        a = -500;
        while (a <= 500) {
            s = NmSkewScore(pts, np, prof, a, off, nb);
            if (s > bs) {
                bs = s;
                best = a;
            }
            a += 10;
        }
        a = best - 9;
        while (a <= (best + 9)) {
            s = NmSkewScore(pts, np, prof, a, off, nb);
            if (s > bs) {
                bs = s;
                best = a;
            }
            a += 1;
        }
        if (bs <= (s0 + (s0 / 64))) {
            return 0;
        }
        return best;
    }
    public static int NmOrient(int osdDeg, int osdConf, int minConf) {
        // The quarter turns CLOCKWISE that make a page upright, from OSD (degrees to rotate clockwise, confidence x10), when
        // its confidence reaches `min-conf` (`nm-osd-conf`); else -1 (the tracer's `tlines` decide later).
        if (osdDeg < 0) {
            return -1;
        }
        if (osdConf < minConf) {
            return -1;
        }
        return (osdDeg / 90) % 4;
    }
    public static int NmReskew(emon.Port.Cells views, int v, int cdeg) {
        // Give view row `v` the deskew `cdeg`, recomputing its transform: a view row is made once, so this builds the
        // row again at the end of the arena, copies it over `v`, and drops it.
        int pg = Evidence.VwGet(views, v, Evidence.VwfPage());
        int kd = Evidence.VwGet(views, v, Evidence.VwfKind());
        int rq = Evidence.VwGet(views, v, Evidence.VwfRequest());
        int pa = Evidence.VwGet(views, v, Evidence.VwfParent());
        int pw = Evidence.VwGet(views, v, Evidence.VwfPxw());
        int ph = Evidence.VwGet(views, v, Evidence.VwfPxh());
        int dp = Evidence.VwGet(views, v, Evidence.VwfDpi());
        int ly = Evidence.VwGet(views, v, Evidence.VwfLayer());
        int ik = Evidence.VwGet(views, v, Evidence.VwfInk());
        int tn = Evidence.VwGet(views, v, Evidence.VwfTurns());
        int cx = Evidence.VwGet(views, v, Evidence.VwfCropx());
        int cy = Evidence.VwGet(views, v, Evidence.VwfCropy());
        int fl = Evidence.VwGet(views, v, Evidence.VwfFlags());
        int r = Evidence.VwNew(views, pg, kd, rq, pa, pw, ph, dp, ly, ik, tn, cdeg, cx, cy, fl);
        int f = 0;
        int x = 0;
        while (f < 24) {
            x = Evidence.VwGet(views, r, f);
            Evidence.VwSet(views, v, f, x);
            f += 1;
        }
        emon.Port.CellsDrop(views, r * 24);
        return 0;
    }
    internal static int NmClamp(int v, int lo, int hi) {
        if (v < lo) {
            return lo;
        }
        if (v > hi) {
            return hi;
        }
        return v;
    }
    public static int NmPermille(int n, int d) {
        // n over d per mille, -1 when d is not positive.
        if (d <= 0) {
            return -1;
        }
        return (int) ((((long) n) * 1000) / ((long) d));
    }
    public static int NmBoxInk(emon.Port.Bitmap m, int bx0, int by0, int bx1, int by1) {
        // Nonzero pixels of `m` in the half-open box, clamped to the bitmap: runs found by `bitmap-next-nonzero`, so the
        // cost follows the ink, not the box.
        int x0 = NmClamp(bx0, 0, emon.Port.BitmapW(m));
        int x1 = NmClamp(bx1, 0, emon.Port.BitmapW(m));
        int y1 = NmClamp(by1, 0, emon.Port.BitmapH(m));
        int y = NmClamp(by0, 0, emon.Port.BitmapH(m));
        int x = 0;
        int n = 0;
        while (y < y1) {
            x = emon.Port.BitmapNextNonzero(m, x0, y);
            while (x < x1) {
                n += 1;
                x = emon.Port.BitmapNextNonzero(m, x + 1, y);
            }
            y += 1;
        }
        return n;
    }
    public static int NmBoxBoth(emon.Port.Bitmap a, emon.Port.Bitmap b, int bx0, int by0, int bx1, int by1) {
        // Pixels of the box nonzero in BOTH `a` and `b` (same size), walking only `a`'s ink.
        int x0 = NmClamp(bx0, 0, emon.Port.BitmapW(a));
        int x1 = NmClamp(bx1, 0, emon.Port.BitmapW(a));
        int y1 = NmClamp(by1, 0, emon.Port.BitmapH(a));
        int y = NmClamp(by0, 0, emon.Port.BitmapH(a));
        int x = 0;
        int n = 0;
        while (y < y1) {
            x = emon.Port.BitmapNextNonzero(a, x0, y);
            while (x < x1) {
                if (emon.Port.BitmapU8(b, x, y, 0) != 0) {
                    n += 1;
                }
                x = emon.Port.BitmapNextNonzero(a, x + 1, y);
            }
            y += 1;
        }
        return n;
    }
    public static int NmBoxGraySum(emon.Port.Bitmap m, emon.Port.Bitmap g, int bx0, int by0, int bx1, int by1) {
        // The sum of `g` over the pixels of the box where `m` is nonzero.
        int x0 = NmClamp(bx0, 0, emon.Port.BitmapW(m));
        int x1 = NmClamp(bx1, 0, emon.Port.BitmapW(m));
        int y1 = NmClamp(by1, 0, emon.Port.BitmapH(m));
        int y = NmClamp(by0, 0, emon.Port.BitmapH(m));
        int x = 0;
        int n = 0;
        while (y < y1) {
            x = emon.Port.BitmapNextNonzero(m, x0, y);
            while (x < x1) {
                n += emon.Port.BitmapU8(g, x, y, 0);
                x = emon.Port.BitmapNextNonzero(m, x + 1, y);
            }
            y += 1;
        }
        return n;
    }
    internal static int NmBoxArea(emon.Port.Bitmap m, int bx0, int by0, int bx1, int by1) {
        return (NmClamp(bx1, 0, emon.Port.BitmapW(m)) - NmClamp(bx0, 0, emon.Port.BitmapW(m))) * (NmClamp(by1, 0, emon.Port.BitmapH(m)) - NmClamp(by0, 0, emon.Port.BitmapH(m)));
    }
    public static int NmFeatOcr(emon.Port.Cells feats, int frow, int x0, int y0, int x1, int y1, emon.Port.Bitmap binary, emon.Port.Bitmap eng, int hasEng, emon.Port.Bitmap body, emon.Port.Bitmap gray, int paper) {
        // An OCR word's ink columns (`xo-*`, SPEC 8.4.5) from its pixel box on the view it was read from: 10 kin ink under
        // the box on the Sauvola `binary` (per mille of the box), 11 the engine's own binary (`eng`, -1 when `has-eng` is
        // 0), 12 the Jaccard of the two inside the box, 13 the share of its ink in the `body` mask, 16 the contrast of its
        // ink: the layer paper's gray (`paper`) minus the mean gray of its ink. A column that cannot be computed is -1.
        int area = NmBoxArea(binary, x0, y0, x1, y1);
        int kin = NmBoxInk(binary, x0, y0, x1, y1);
        int en = 0;
        int both = 0;
        int un = 0;
        int gs = 0;
        Evidence.FeSet(feats, frow, Evidence.XoKinInk(), NmPermille(kin, area));
        if (hasEng == 1) {
            en = NmBoxInk(eng, x0, y0, x1, y1);
            both = NmBoxBoth(binary, eng, x0, y0, x1, y1);
            un = (kin + en) - both;
            Evidence.FeSet(feats, frow, Evidence.XoEngineInk(), NmPermille(en, area));
            if (un > 0) {
                Evidence.FeSet(feats, frow, Evidence.XoJaccard(), NmPermille(both, un));
            } else {
                Evidence.FeSet(feats, frow, Evidence.XoJaccard(), -1);
            }
        } else {
            Evidence.FeSet(feats, frow, Evidence.XoEngineInk(), -1);
            Evidence.FeSet(feats, frow, Evidence.XoJaccard(), -1);
        }
        if (kin > 0) {
            Evidence.FeSet(feats, frow, Evidence.XoBodyShare(), NmPermille(NmBoxBoth(binary, body, x0, y0, x1, y1), kin));
            gs = NmBoxGraySum(binary, gray, x0, y0, x1, y1);
            Evidence.FeSet(feats, frow, Evidence.XoInkGray(), NmClamp(paper - (gs / kin), 0, 255));
        } else {
            Evidence.FeSet(feats, frow, Evidence.XoBodyShare(), -1);
            Evidence.FeSet(feats, frow, Evidence.XoInkGray(), -1);
        }
        return kin;
    }
    public static int NmFeatText(emon.Port.Cells feats, int frow, int x0, int y0, int x1, int y1, emon.Port.Bitmap withBin, emon.Port.Bitmap noBin, int hasNo, emon.Port.Bitmap body) {
        // A text-layer word's ink columns (`xt-*`) from its pixel box: 10 ink under it on the `with-text` render's binary,
        // 11 ink under it on the `no-text` render's (text drawn over ink; -1 without one), 12 the share of its ink in the
        // `with-text` body mask.
        int area = NmBoxArea(withBin, x0, y0, x1, y1);
        int kin = NmBoxInk(withBin, x0, y0, x1, y1);
        Evidence.FeSet(feats, frow, Evidence.XtKinInk(), NmPermille(kin, area));
        if (hasNo == 1) {
            Evidence.FeSet(feats, frow, Evidence.XtInkWithoutText(), NmPermille(NmBoxInk(noBin, x0, y0, x1, y1), area));
        } else {
            Evidence.FeSet(feats, frow, Evidence.XtInkWithoutText(), -1);
        }
        if (kin > 0) {
            Evidence.FeSet(feats, frow, Evidence.XtBodyShare(), NmPermille(NmBoxBoth(withBin, body, x0, y0, x1, y1), kin));
        } else {
            Evidence.FeSet(feats, frow, Evidence.XtBodyShare(), -1);
        }
        return kin;
    }
    public static int NmBoxPx(emon.Port.Cells views, int v, int x0, int y0, int x1, int y1, emon.Port.Cells res, int off) {
        // A page box (centipoints) as a pixel box of view `v`, the smallest around its four mapped corners, written to
        // `res[off..off+3]` as x0 y0 x1 y1 (half-open: the far edge is one past the last pixel). Corners map through
        // `vw-cpt-to-px`, so quarter turns and deskew are honoured.
        int ax = Evidence.VwCptToPx(views, v, 0, x0, y0);
        int ay = Evidence.VwCptToPx(views, v, 1, x0, y0);
        int bx = Evidence.VwCptToPx(views, v, 0, x1, y0);
        int by = Evidence.VwCptToPx(views, v, 1, x1, y0);
        int cx = Evidence.VwCptToPx(views, v, 0, x0, y1);
        int cy = Evidence.VwCptToPx(views, v, 1, x0, y1);
        int dx = Evidence.VwCptToPx(views, v, 0, x1, y1);
        int dy = Evidence.VwCptToPx(views, v, 1, x1, y1);
        int mnx = ax;
        int mxx = ax;
        int mny = ay;
        int mxy = ay;
        if (bx < mnx) {
            mnx = bx;
        }
        if (cx < mnx) {
            mnx = cx;
        }
        if (dx < mnx) {
            mnx = dx;
        }
        if (bx > mxx) {
            mxx = bx;
        }
        if (cx > mxx) {
            mxx = cx;
        }
        if (dx > mxx) {
            mxx = dx;
        }
        if (by < mny) {
            mny = by;
        }
        if (cy < mny) {
            mny = cy;
        }
        if (dy < mny) {
            mny = dy;
        }
        if (by > mxy) {
            mxy = by;
        }
        if (cy > mxy) {
            mxy = cy;
        }
        if (dy > mxy) {
            mxy = dy;
        }
        emon.Port.CellsSet(res, off, mnx);
        emon.Port.CellsSet(res, off + 1, mny);
        emon.Port.CellsSet(res, off + 2, mxx);
        emon.Port.CellsSet(res, off + 3, mxy);
        return 0;
    }
    public static int NmView(emon.Port.Cells views, emon.Port.Cells inks, int page, int srcview, emon.Port.Bitmap src, emon.Port.Bitmap gray, emon.Port.Bitmap binary, emon.Port.Cells ws, emon.Port.Cells sv, emon.Port.Cells aux) {
        // Normalize ONE raster: `src` is the bitmap of `views` row `srcview` (a render or a decode); `gray` and `binary` are
        // 1-channel bitmaps of its size that the caller made. Fills `gray` (`bitmap-gray-into`) and `binary` (banded Sauvola, or
        // a plain threshold for a bilevel source), clusters the ink layers into `ws` (so `nm-mask-into` can make any layer's
        // mask after), appends the `views` rows (gray, binary, and one ink-mask per layer) and `inks` rows, guesses roles, and
        // for a decode view measures the skew, writing it to the source row and to every view derived from it. `sv` and
        // `aux` are scratch `Cells`. Answers the number of ink layers. See the header for the wiring point.
        int pxw = emon.Port.BitmapW(src);
        int pxh = emon.Port.BitmapH(src);
        int dpi = Evidence.VwGet(views, srcview, Evidence.VwfDpi());
        int kind = Evidence.VwGet(views, srcview, Evidence.VwfKind());
        int layer = Evidence.VwGet(views, srcview, Evidence.VwfLayer());
        int turns = Evidence.VwGet(views, srcview, Evidence.VwfTurns());
        int cropx = Evidence.VwGet(views, srcview, Evidence.VwfCropx());
        int cropy = Evidence.VwGet(views, srcview, Evidence.VwfCropy());
        int nl = 0;
        int bin = 0;
        int other = 0;
        int ang = Evidence.VwGet(views, srcview, Evidence.VwfDeskew());
        int r = 0;
        int irow = 0;
        int k = 0;
        int mrow = 0;
        emon.Port.BitmapGrayInto(src, gray);
        NmWsInit(ws);
        emon.Port.BitmapHistRgb(src, ws, NmWsHist());
        nl = NmLayers(ws, NmInkMerge(), NmInkPaper(), NmInkMin(), NmInkSpike());
        NmRoles(ws, NmInkLight(), NmInkChroma(), NmInkBg());
        // a bilevel source has pixels in bin 0 and bin 4095 only
        while (bin < 4096) {
            if (emon.Port.CellsAt(ws, NmWsHist() + bin) != 0) {
                if (bin != 0) {
                    if (bin != 4095) {
                        other = 1;
                    }
                }
            }
            bin += 1;
        }
        // the skew is read off the BODY layers' ink (the body mask is borrowed `binary`, which is made after): a coloured
        // seal, a light watermark or a texture has its own geometry and must not vote
        if (kind == Evidence.VkDecode()) {
            NmRoleMaskInto(src, ws, Evidence.IrBody(), binary);
            ang = NmDeskew(binary, aux, sv);
            if (ang != Evidence.VwGet(views, srcview, Evidence.VwfDeskew())) {
                NmReskew(views, srcview, ang);
            }
        }
        if (other == 0) {
            emon.Port.BitmapThresholdInto(gray, 127, binary);
        } else {
            NmSauvola(gray, binary, NmSauvolaR(dpi), NmSauvolaK(), sv);
        }
        r = Evidence.VwNew(views, page, Evidence.VkGray(), -1, srcview, pxw, pxh, dpi, layer, -1, turns, ang, cropx, cropy, 0);
        emon.Port.CellsSet(ws, NmWsMisc() + 4, r);
        r = Evidence.VwNew(views, page, Evidence.VkBinary(), -1, srcview, pxw, pxh, dpi, layer, -1, turns, ang, cropx, cropy, 0);
        emon.Port.CellsSet(ws, NmWsMisc() + 5, r);
        irow = NmInkRows(inks, ws, page, srcview);
        while (k < nl) {
            mrow = Evidence.VwNew(views, page, Evidence.VkInkMask(), -1, srcview, pxw, pxh, dpi, layer, irow + k, turns, ang, cropx, cropy, 0);
            Evidence.IkSet(inks, irow + k, Evidence.IkfMask(), mrow);
            k += 1;
        }
        return nl;
    }
}
